return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Swahili','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 22:30+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'sw','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" imehifadhiwa.','"%1$s" created. %2$d template updated.'=>'"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.' . "\0" . '"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.','"%s" created.'=>'"%s" imetengenezwa.','"product" (replaces "article")'=>'"bidhaa" (inachukua nafasi ya "makala")','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d herufi — nzuri, juu kidogo ya kiwango bora cha %2$d lakini ndani ya kiwango kinachokubalika cha herufi %3$d. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d herufi — urefu bora. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d herufi — huenda ikakatwa kwenye matokeo ya utafutaji (baki chini ya %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d herufi — fupi sana (lengo ni %2$d–%3$d). %4$s','%1$d internal, %2$d external.'=>'%1$d ndani, %2$d nje.','%1$d of %2$d image(s) missing alt text.'=>'%1$d ya %2$d picha hazina maandishi ya alt.','%1$d words — below recommended minimum of %2$d.'=>'%1$d maneno — chini ya kiwango cha chini kinachorekomendwa cha %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d maneno — maudhui machache sana. Fikiria kupanua hadi angalau %2$d maneno.','%d chars — good length.'=>'%d herufi — urefu mzuri.','%d external link(s), no internal links.'=>'Kiungo cha nje cha %d, hakina viungo vya ndani.','%d external link(s), no internal links. Add internal links to related content.'=>'%d kiungo nje, hakuna viungo vya ndani. Ongeza viungo vya ndani kwa maudhui yanayohusiana.','%d H1 tags found — a page should have exactly one H1.'=>'%d lebo za H1 zimepatikana — ukurasa unapaswa kuwa na H1 moja tu.','%d image(s), all have alt text.'=>'%d picha, zote zina maandishi ya alt.','%d language not yet linked'=>'Lugha %d bado haijaundwa' . "\0" . 'Lugha %d bado hazijaundwa','%d link updated.'=>'%d kiungo kimesasishwa.' . "\0" . '%d viungo vimesasishwa.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Faili %d za lugha haziwezi kufutwa kiotomatiki (DISALLOW_FILE_MODS imewashwa). Futa kwa mikono kupitia seva yako au WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Faili %d za lugha haziwezi kufutwa kiotomatiki (DISALLOW_FILE_MODS imewashwa). Futa kwa mikono kupitia seva yako au WP-CLI: wp language core uninstall <locale>.','%d locale file removed.'=>'Faili %d za lugha zimetolewa.' . "\0" . 'Faili %d za lugha zimetolewa.','%d locale pack installed.'=>'%d pakiti za lugha zimewekwa.' . "\0" . '%d pakiti za lugha zimewekwa.','%d navigation reference updated.'=>'%d marejeo ya urambazaji yamesasishwa.' . "\0" . '%d marejeo ya urambazaji yamesasishwa.','%d part reference updated.'=>'%d marejeo ya sehemu yamesasishwa.' . "\0" . '%d marejeo ya sehemu yamesasishwa.','%d words.'=>'%d maneno.','%s Archive'=>'Hifadhi %s','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s ni hai na tayari inatoa Schema.org JSON-LD. Lingua Forge imezima toleo lake la schema ili kuzuia michoro inayopingana. Tofauti na Open Graph — ambapo LF huongeza og:locale juu ya toleo la plugin nyingine — schema haiwezi kuongezwa kwa usafi: michoro ya JSON-LD inayojirudia au inayokinzana husababisha makosa ya uthibitishaji. Zima toleo la schema kwenye plugin iliyogunduliwa ikiwa unataka LF kushughulikia data iliyowekwa muundo.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s ni hai na inazalisha ramani yake ya tovuti. Ramani hiyo ni tofauti na ya LF. Zote zinapaswa kuwasilishwa kwa Google Search Console: ramani ya SEO inaorodhesha maudhui yako; ramani ya LF huongeza viungo mbadala vya lugha nyingi. Ramani ya LF inatangazwa moja kwa moja kwenye robots.txt.','(avg %.1f hits/block)'=>'(avg %.1f mafanikio/kipande)','(avg %.1f hits/entry)'=>'(wastani %.1f hits/kuingia)','(disabled)'=>'(imezimwa)','(no title) #%d'=>'(hakuna kichwa) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} hayakuwa na viungo vinavyoweza kubadilishwa — chunguza tena kwa uchunguzi)','.txt file(s) in the directory'=>'.txt faili(za) kwenye saraka','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'H1 1 ✓ — hakuna vichwa vidogo vya H2 (inayokubalika kwa aina hii ya maudhui).','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'H1 moja ✓ — hakuna vichwa vya H2 vilivyopatikana. Kuongeza H2 huimarisha muundo.','1 H1 ✓, %1$d H2, %2$d H3.'=>'H1 moja ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d kiolezo zilizotafsiriwa kutoka kwa mandhari &#8220;%2$s&#8221; zimehifadhiwa kwenye hifadhidata lakini kwa sasa hazifanyi kazi. Zitatumika tena ikiwa utarejesha hali ya mandhari hiyo. Ili kuhamisha tafsiri zako kwa mandhari mpya, zitengeneze tena kupitia <strong>Mipangilio → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> kiungo kinachoweza kurekebishwa kiotomatiki','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> kiungo kinachohitaji mapitio ya mikono','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> njia/nyingine zilizobaki','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> tatizo la kiolezo','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Kuna faili halali ya robots.txt kwenye mzizi wa tovuti. WordPress\'s virtual robots.txt — na LF\'s Sitemap: filter — zinapita. Ramani ya LF haijatangazwa kwa injini za utafutaji.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Inakubali faili zilizokusanywa za .mo pekee. Jina la faili lazima zifuate muundo wa {textdomain}-{locale}.mo. Kupakia faili lenye jina sawa na la zamani kutalibadilisha.','Action'=>'Kitendo','Actions'=>'Vitendo','active'=>'kinachofanya kazi','Active Languages'=>'Lugha Zinazotumika','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Lugha zinazotumika: ongeza kila lugha unayotaka kuunga mkono. Kila lugha hupata kiambatanisho cha URL au subdomain na lebo ya hreflang kwenye &lt;head&gt; ya ukurasa.','Active Provider'=>'Mtoa huduma wa Sasa','Add entry'=>'Ongeza kiingilio','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Ongeza maelekezo ili kuboresha rasimu — mfano fupisha, ongeza sehemu ya hitimisho, tumia muundo rasmi zaidi, jumuisha sehemu ya maswali yanayoulizwa mara kwa mara…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Ongeza maelekezo ya kuboresha rasimu — mfano, ifupishe, ongeza sehemu ya hitimisho, tumia muundo rasmi zaidi…','Add new entry'=>'Ongeza kiingilio kipya','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Ongeza neno moja kwa kila mstari. Neno la chanzo na uwasilishaji wa lengo vinahitajika. Jozi ya lugha huamua kazi za tafsiri zinazotumika na masharti.','Add Sitemap directive to robots.txt'=>'Ongeza amri ya Ramani ya Tovuti kwenye robots.txt','Add the following line to your robots.txt manually:'=>'Ongeza mstari ufuatao kwenye robots.txt kwa mikono:','Add WooCommerce product tags to Open Graph output'=>'Ongeza lebo za bidhaa za WooCommerce kwenye matokeo ya Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Ongeza kiungo cha ukurasa wa nyumbani ili wageni waweze kuvinjari kwa lugha yao.','Administrators only (manage_options)'=>'Wasimamizi pekee (simamia_mipangilio)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Baada ya kubadilisha lugha kuu, safisha permalink (sehemu chini) ili kusasisha njia ya URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Baada ya kubadilisha mipangilio ya muundo wa URL (kianzio cha njia ↔ subdomain), daima tembelea Mipangilio → Permalinks na bofya Hifadhi Mabadiliko ili kufuta sheria za kuandika upya.','AI analysis failed. Please try again.'=>'Uchambuzi wa AI umeshindwa. Tafadhali jaribu tena.','AI Behaviour Preset'=>'Mipangilio ya Tabia za AI','AI cache cleared. %d entry was removed.'=>'Cache ya AI imefutwa. Kipengee %d kiliondolewa.' . "\0" . 'Cache ya AI imefutwa. Vipengee %d vimeondolewa.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Cache: inaorodhesha majibu ya AI yaliyohifadhiwa na idadi za mafanikio. Futa cache yote au vitu vya chapisho kimoja. Tumia "Futa" kabla ya kujaribu mabadiliko ya tafsiri — matokeo yaliyohifadhiwa yanarudiwa hata unapotabadilisha preset au mfano wa AI hadi kifurushi cha cache kitakapotolewa.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Vipengele vya AI ni hiari. Mwelekeo wa lugha, hreflang, kisakinishi cha lugha, na mfumo wa kikundi cha tafsiri vyote vinafanya kazi bila mtoa huduma aliyesakinishwa.','AI Limits & Security'=>'Mipaka na Usalama wa AI','AI provider returned an empty response.'=>'Mtoa huduma wa AI alirudisha majibu tupu.','AI Recommendations'=>'Mapendekezo ya AI','AI returned an unexpected response format. Please try again.'=>'AI imerudisha muundo wa majibu usiotarajiwa. Tafadhali jaribu tena.','AI Usage'=>'Matumizi ya AI','AI Usage & Cache'=>'Matumizi ya AI na Cache','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Lenga kwa herufi 120–160. Acha tupu ili kutumia muhtasari wa nyuma.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Injini kuu za utafutaji — Google, Bing, na Yandex — huweza kugundua ramani ya tovuti kiotomatiki kupitia amri ya Sitemap: kwenye robots.txt. Hakuna hatua ya mikono inayohitajika. Vitufe chini vinatuma ping ya haraka ili injini irudie ramani ya tovuti sasa badala ya kusubiri ukaguzi wa robots.txt ujao.','All time'=>'Wakati wote','All types'=>'Aina zote','Allow editors to lock individual blocks'=>'Ruhusu wahariri kufunga blocks binafsi','Allow Gutenberg template-editing mode on post screens'=>'Ruhusu hali ya uhariri wa template wa Gutenberg kwenye skrini za chapisho','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Pia futa uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, kamusi, na Kumbukumbu ya Tafsiri wakati programu inafutwa.','Also generate meta description'=>'Pia tengeneza maelezo meta','Alternative (server-side):'=>'Mbali (upande wa seva):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Daima toa tu og:locale na og:locale:alternate. Tumia wakati plugin au mandhari nyingine inashughulikia seti kamili ya OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Daima toa seti kamili ya OG + Twitter Card bila kujali plugins nyingine. Tumia tu ikiwa hakuna plugin nyingine inatoa lebo za OG.','An unknown error occurred.'=>'Hitilafu isiyojulikana imetokea.','Analyse…'=>'Chambua…','Analysis'=>'Uchambuzi','Analysis request failed. Please try again.'=>'Ombi la uchambuzi limekosa mafanikio. Tafadhali jaribu tena.','Analyzing…'=>'Inachambua…','and'=>'na','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'yote','API calls saved by cache'=>'Vito vya API vilivyohifadhiwa na cache','API Key'=>'Funguo la API','API Keys'=>'Vifunguo vya API','API Keys Tab'=>'Kipindi cha Funguo za API','API Response Cache'=>'Cache ya Majibu ya API','Appends the following line to your existing robots.txt: %s'=>'Inasababisha mstari ufuatao kwenye robots.txt yako iliyopo: %s','Applied ✓'=>'Imethibitishwa ✓','Apply failed — please try again.'=>'Umeomba kushindwa — tafadhali jaribu tena.','Apply to Block'=>'Tumia kwa Kizuizi','Apply to Editor'=>'Tumia kwa Mhariri','Apply to Footnote'=>'Tumia kwa Nukuu','Apply to Meta Description'=>'Tumia kwa Maelezo ya Meta','Apply translation'=>'Tumia tafsiri','Applying…'=>'Inatumika…','Approximate size'=>'Ukubwa wa takriban','Archive'=>'Makala','Archive: %s'=>'Hifadhi: %s','Article / WebPage'=>'Makala / Tovuti','Article / WebPage — all singular posts and pages'=>'Makala / Tovuti — post na kurasa zote za pekee','Authors and above (edit_published_posts)'=>'Waandishi na zaidi (hariri_maandishi_yaliyochapwa)','Auto (recommended)'=>'Automu (inapendekezwa)','Behavior'=>'Tabia','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Tabia: chagua preset ya AI (Literal, Balanced, Creative), ongeza maagizo maalum ya tovuti kwa ujumla, wezesha au zima tafsiri ya otomatiki baada ya kuhifadhi chapisho, na weka kumbukumbu ya Tafsiri.','Block Content'=>'Yaliyomo ya Kifungu','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Huonyesha arifa ya heshima wakati ukurasa wa sasa unaonyeshwa kwa lugha yake ya asili kwa sababu hakuna tafsiri inayopo kwa lugha ya mgeni. Inasababishwa na ishara ya LINGUAFORGE_LANG_FALLBACK_ACTIVE ya mtaalamu wa Lingua Forge — haitoi chochote wakati kuna tafsiri kwa eneo la ombi.','Block Editor'=>'Mhariri wa Block','block keywordfallback'=>'kuzingatia','block keywordi18n'=>'i18n','block keywordlanguage'=>'lugha','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'tafsiri','Block locking'=>'Kufunga kwa block','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Mipango ya block zilizoorodheshwa kwa aina za machapisho maalum. Tumia kitufe cha Tafsiri kuunda toleo la lugha. Yaliyomo yaliyotafsiriwa yanahifadhiwa hapa na yanaweza kuhamishwa kwenye chapisho lolote la CPT kutoka kwa mhariri wa block au kutumika kama hatua ya kuanzia kwa Pattern iliyosawazishwa (Reusable Block).','block titleMissing Translation Notice'=>'Arifa ya Tafsiri Iliyokosewa','Block translation reuses'=>'Matumizi ya upya wa tafsiri za blok','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Cache ya tafsiri za kiwango cha blok inayoshirikiana kati ya machapisho. Wakati imewezeshwa, blokii zinazofanana (alama sawa, jozi ya lugha, na kamusi) zinatumikia kutoka kwa kumbukumbu badala ya kuita AI tena. Weka mipangilio katika Mipangilio → Tabia.','Blog / Editorial'=>'Blogu / Mhariri','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Post za blog hutumia Article; aina nyingine za post na kurasa zote hutumia WebPage. Inajumuisha kichwa, maelezo, inLanguage, url, tarehe iliyochapishwa, tarehe iliyobadilishwa, picha, na mchapishaji.','Browser language redirect'=>'Uelekeaji wa lugha wa kivinjari','Built-in preset instructions:'=>'Maagizo ya awali yaliyowekwa ndani:','Bulletize (•-prefixed)'=>'Fanya kwa alama za orodha (•-kianzio)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Hifadhi sawa za tafsiri kwenye kiwango cha block ili maudhui yanayoweza kutumika tena (viambatanisho vya chini, upendeleo wa upande, accordions, sehemu za kisheria zenye boilerplate nyingi) zisitoe wito wa API kila wakati. Wakati imewezeshwa, mchakato wa tafsiri huparsing kila chapisho kuwa blocks, huangalia kila block kwenye hifadhi, na hupeleka blocks zisizo na hifadhi pekee kwa AI kwa ombi moja la kundi. Mabadiliko ya kamusi na mabadiliko ya preset ya Uzingatiaji huondoa hifadhi za tafsiri zinazohusika kiotomatiki. Tazama takwimu na safisha hifadhi chini ya Matengenezo.','cached'=>'imehifadhiwa','Cached API responses'=>'Majibu ya API yaliyohifadhiwa','Cached block translations'=>'Tafsiri za blokii zilizohifadhiwa','Cancel'=>'Ghairi','Cannot determine target language from slug.'=>'Haiwezi kubaini lugha lengwa kutoka kwa slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Haiwezi kuandika kwa bidhaa %1$d: ni toleo lililotafsiriwa (lugha: %2$s)%3$s. Data ya kiutendaji (bei, hisa, SKU, vipimo) inapaswa kusasishwa kwenye bidhaa chanzo. Suluhisha ID ya bidhaa chanzo kupitia: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>' Lebo la Canonical','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Kataza kiasi cha matumizi ya AI kinachoweza kuzalishwa na tovuti na kuzuia majukumu ya watumiaji wanaoweza kuanzisha simu za AI zilipwa. Inachukua nafasi ya kikomo cha kila mtumiaji (ombi 30 / dakika, kilichowekwa kwa nguvu) kinacholinda dhidi ya mizunguko ya kipekee ya mtumiaji.','chars'=>'wahusika','Chunk translated'=>'Sehemu iliyotafsiriwa','Chunk translated to:'=>'Sehemu iliyotafsiriwa kwa:','Clear'=>'Futa','Clear All'=>'Futa Yote','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Futa matokeo yote ya AI yaliyohifadhiwa? Maombi yajayo yataanzisha wito mpya wa API hadi cache itakapojengwa upya.','Clear API Response Cache'=>'Futa Cache ya Majibu ya API','Clear Debug Files'=>'Futa Faili za Kagua','Clear hints'=>'Futa vidokezo','Clear input'=>'Futa ingizo','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Futa Kumbukumbu ya Tafsiri yote? Tafsiri za baadaye zitajenga tena cache wanapozalishwa.','Clear Translation Memory'=>'Futa Kumbukumbu ya Tafsiri','Close'=>'Funga','Close language panel'=>'Funga paneli ya lugha','Close popover'=>'Funga kidirisha','Compatibility'=>' Ulinganifu','Compliance Preset'=>'Preset ya Uzingatiaji','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Sanidi mtoa huduma wa AI katika Settings → API Keys ili kuwezesha mapendekezo yanayotegemea AI.','Content generated'=>'Yaliyomo yamezalishwa','Content Generator'=>'Kizazi cha Maudhui','Content ready'=>'Yaliyomo yamekamilika','Contributors and above — default (edit_posts)'=>'Wachangia na zaidi — chaguo-msingi (hariri_maandishi)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Dhibiti kiasi cha maudhui yanayopitishwa kwa AI na ukubwa wa majibu yanayoweza kutolewa. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama mahali pa kuweka). Ongeza thamani hizi ikiwa kurasa kubwa zinakatwa; punguza ili kupunguza gharama za API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Hudhibiti bajeti ya tokeni na mipaka ya ingizo kwa kipengele cha Kizazi cha Maudhui cha AI. Acha mashamba tupu ili kutumia chaguo-msingi zilizojengwa ndani.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Hakikisha kinachotokea wakati msimamizi anafuta programu kutoka kwa Plugins → Plugins zilizowekwa → Futa. Mipangilio ya programu na cache za AI daima zinasafishwa. Uteuzi wa lugha na uhusiano wa tafsiri huzingatiwa kwa chaguo-msingi ili kusudi la kufuta au kufunga upya liweze kuendelea mahali pa kuacha.','Conversational'=>' Mazungumzo','Copied ✓'=>'Imenakiliwa ✓','Copy'=>'Nakili','Copy failed — please copy the URL manually.'=>'Nakili imekosa — tafadhali nakili URL kwa mikono.','Copy markup'=>'Nakili muundo wa maandishi','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Nakili URL ya sasa kwenye ubao wa kunakili. Inaonyesha toast ya "Kiungo kimenakiliwa" kwa mafanikio.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Nakili matokeo na uyatamise mahali panahitajika (kama moja kwa moja kwenye uwanja wa maelezo mafupi).','Copy to safe storage'=>'Nakili kwenye hifadhi salama','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'vitendo vya nakala / asili / otomatiki: vinashughulikiwa na LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'Haiwezi kuongezea kiingilio: neno la chanzo na neno la malengo linahitajika.','Could not copy the file. Check that the uploads folder is writable.'=>'Haiwezekani kunakili faili. Hakikisha folda ya uploads ina haki ya kuandika.','Could not instantiate the provider.'=>'Haiwezi kuanzisha mtoa huduma.','Could not save the file. Check that the uploads folder is writable.'=>'Haiwezekani kuhifadhi faili. Hakikisha folda ya uploads ina haki ya kuandika.','Could not save the glossary entry.'=>'Haiwezi kuokoa kiingilio cha kamusi ya msamiati.','Could not write to robots.txt. Check file permissions.'=>'Haiwezi kuandika kwa robots.txt. Angalia ruhusa za faili.','CPT Block Patterns'=>'Mipango ya Block CPT','Create'=>'Unda','Create missing'=>'Unda zilizokosewa','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Kuunda tafsiri za aina ya chapisho "%s" kunahitaji muunganisho hai. Tafadhali hakikisha muunganisho unaohitajika umewekwa na kufanya kazi.','Creating…'=>'Inaundwa…','Creative / Marketing'=>'Ubunifu / Masoko','Creative / Marketing instructions'=>'Maagizo ya Ubunifu / Masoko','Current content (will be overwritten)'=>'Yaliyomo ya sasa (yatafutwa)','Current status'=>'Hali ya sasa','Current title'=>'Kichwa cha sasa','Current: {current}'=>'Sasa: {current}','Currently emitting'=>'Kwa sasa inatoa','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Kwa sasa urithi kutoka kwa kifungo cha %s. Kuchagua thamani hapa kutaleta mabadiliko.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Kwa sasa inakosewa kwa posts zinazotumia vigezo vya placeholder vya block-comment (wp:details fields za muhtasari, n.k.) — zinapita kwa njia ya tafsiri ya wito mmoja iliyopo.','Currently:'=>'Sasa hivi:','Custom'=>'Maendeleo Maalum','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Kiwango cha AI cha kila siku kimefikia (%1$d maombi). Kinarejeshwa saa %2$s UTC.','Daily request limit'=>'Kikomo cha maombi ya kila siku','Danger Zone'=>'Eneo la Hatari','Debug Files'=>'Faili za Kagua','Debug files cleared. %d file was removed.'=>'Faili za kagua zimesafishwa. Faili %d imeondolewa.' . "\0" . 'Faili za kagua zimesafishwa. Faili %d zimeondolewa.','Debug logging'=>'Kumbukumbu za kagua','Debug logging disabled.'=>'Kumbukumbu za kagua zimezimwa.','Debug logging enabled.'=>'Kumbukumbu za kagua zimewezeshwa.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Kagua: wezesha rekodi ya kagua ili kukamata maombi ya AI na majibu ya API kwa faili la ndani. Zima baada ya utatuzi wa matatizo — hali ya kagua inaandika faili kwa kila ombi la AI.','Default OG image'=>'Picha ya OG chaguo-msingi','Delete'=>'Futa','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Futa faili zote za .txt kwenye saraka ya kagua? Saraka yenyewe itabaki ili kuendelea kuandika mafaili ya kagua ya baadaye.','Delete all files for this override (both .mo and .po)?'=>'Futa faili zote za mabadiliko haya (zote .mo na .po)?','Delete content data on uninstall'=>'Futa data ya maudhui wakati wa kufuta','Delete this glossary entry?'=>'Unataka kufuta kiingilio hiki cha kamusi? ','Describe what to write — topic, key points, structure…'=>'Eleza kinachopaswa kuandikwa — mada, vidokezo muhimu, muundo…','Details ↗'=>'Maelezo ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Gundua programu-jalizi za SEO zinazofanya kazi (Yoast, Rank Math, n.k.) wakati wa runtime. Toa tu og:locale + og:locale:alternate wakati programu-jalizi nyingine tayari inatoa seti kamili ya OG; toa seti kamili wakati hakuna inayoonekana.','Directory'=>'Saraka','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Zima wakati wa kurekebisha maombi au unapoihitaji kila ombi lifikie mtoa huduma wa AI. Kuzima hakufutii vitu vilivyohifadhiwa — kuirudisha tena huwarejesha. Kuongeza matumizi ya API mara moja kwenye tovuti zenye shughuli nyingi kunatarajiwa wakati imezimwa.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Zima tu kwa tovuti zisizo na kichwa au utekelezaji wa hreflang wa kawaida. Wakati imezimwa, LF haitoi tena lebo ya canonical ya WordPress na haitasawazisha matokeo ya programu-jalizi za SEO za hreflang.','Disabled'=>'Imelazimishwa','Disabled (by setting)'=>'Imelazimishwa (kwa kuweka)','Disabled (mode setting)'=>'Imelazimishwa (uwezo wa mode)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Imelazimishwa kwa sababu mu-plugin ya lf-social-share tayari inatoa huduma hii.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS imewekwa.','Display'=>'Onyesha','Displays the Lingua Forge language switcher.'=>'Inaonyesha kigeuzi cha lugha cha Lingua Forge.','Do not output any OG tags.'=>'Usitoe lebo yoyote ya OG.','Documentation'=>'Nyaraka','Done'=>'Imekamilika','Done — {done} of {total} post(s) fixed.'=>'Imekamilika — machapisho {done} kati ya {total} yamerekebishwa.','Down'=>'Chini','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pakua na usakinishe pakiti ya lugha kuu ya WordPress moja kwa moja kutoka WordPress.org. Mara baada ya kusakinisha, lugha inapatikana kwa uelekezaji wa URL na mchakato wa tafsiri wa AI. Orodha ya lugha zinazopatikana inachukuliwa kwa ombi — bofya kitufe chini ili kuipakua.','Dropdown direction'=>'Mwelekeo wa orodha','edit'=>'hariri','Editors and above (edit_others_posts)'=>'Wahariri na zaidi (hariri_wa_waandishi_wengine)','Enable API response caching'=>'Wezesha kuhifadhi majibu ya API','Enable block-level translation cache reuse across posts'=>'Wezesha upyaji wa hifadhi ya tafsiri kwenye block kwa posts','Enable Social Share URL rewriting for Social Icons blocks'=>'Wezesha upya URL za Shirika la Kijamii kwa vikundi vya Ikoni za Kijamii','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Washa wakati mada yako inatoa kichwa cha chapisho kama H2 badala ya H1 (ya kawaida katika baadhi ya mandhari za blok). Mchambuzi huinua ukurasa uliotolewa na, ikiwa haioni H1 bali hupata H2, huinua H2 ya kwanza kuwa H1 kwa ajili ya alama za alama.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Ingiza ufunguo wako wa API kwa angalau mtoa huduma mmoja wa AI. Funguo zimehifadhiwa kwa usalama kwa kutumia AES-256-GCM na siri maalum ya tovuti (LINGUAFORGE_SECRET). Usishiriki usafirishaji wa hifadhidata bila kubadilisha siri kwanza.','environment variable'=>'mabadiliko ya mazingira','Error'=>'Hitilafu','Expand'=>'Panua','Expected: {expected}'=>'Inatarajiwa: {expected}','External share services'=>'Huduma za ushirikiano za nje','Extra guidance — tone, style, constraints, target audience…'=>'Msaada wa ziada — sauti, mtindo, vizuizi, hadhira lengwa…','Extra guidance — tone, style, constraints…'=>'Msaada wa ziada — sauti, mtindo, vizuizi…','Failed. Please try again.'=>'Imeshindwa. Tafadhali jaribu tena.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL ya picha ya mbadala inayotumika wakati ukurasa hauja na picha maarufu, nembo ya tovuti, au ikoni ya tovuti. Inaonyeshwa katika maoni ya kijamii kwa hifadhidata, faharasa ya blogu, na kurasa zozote za pekee bila picha ndogo.','Feature'=>'Kipengele','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Vipengele vimegawanywa katika ngazi mbili. Ingiza kitambulisho halisi cha mfano kwa kila ngazi na mtoa huduma. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama nafasi ya kujaza). Mifano ya mtoa huduma anayeendesha pekee ndiyo inaitwa wakati wa runtime — weka zingine mapema ikiwa unakusudia kubadilisha.','File copied to safe storage successfully.'=>'Faili imehamishwa kwa mafanikio kwenye hifadhi salama.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Mabadiliko ya faili yamezimwa (DISALLOW_FILE_MODS).','Files'=>'Faili','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Faili huwasili kwenye saraka iliyo chini. Inafaa kwa utatuzi wa matatizo ya tafsiri — zima mara unapata unachohitaji ili faili zisikusanyike. Pia unaweza kuizuia kutoka wp-config.php kwa kutumia `define( \'LINGUAFORGE_AI_DEBUG\', true );` ambayo inazidi kitufe hiki.','Filter'=>'Kichujio','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Chuja kwa lugha na aina ya chapisho, tembelea maudhui yako, na bofya Tathmini kwa kipengele chochote ili kuendesha ukaguzi wa SEO wa kanuni — urefu wa kichwa, maelezo ya meta, idadi ya maneno, muundo wa vichwa, ufunuo wa picha ya alt, na viungo vya ndani.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Chuja kwa kutumia linguaforge_debug_dir ili kuelekeza matokeo ya kagua mahali pasipo umma.','Finding'=>'Utafutaji','Fix'=>'Rekebisha','Fix All'=>'Rekebisha Yote','Fix all links'=>'Rekebisha viungo vyote','Fix all parts'=>'Rekebisha sehemu zote','Fix Links'=>'Rekebisha Viungo','Fix Nav'=>'Rekebisha Urambazaji','Fix Parts'=>'Rekebisha Sehemu','Fix Template'=>'Rekebisha Kiolezo','Fixing {n} / {total}…'=>'Rekebisha {n} / {total}…','Fixing…'=>'Inarekebishwa…','Flush Permalink Rules'=>'Fanya usafi wa Sheria za Permalink','Flush Permalinks'=>'Fanya usafi wa Permalinks','Flush Sitemap Cache'=>'Fagia Hifadhi ya Ramani','Footnote Content'=>'Maudhui ya Nukuu','footnote(s) translated — applied together with content.'=>'Vijisehemu vilivyotafsiriwa — vimewekwa pamoja na yaliyomo.','Footnotes'=>'Vijisehemu','Footnotes payload (advanced)'=>'Msaada wa maelezo ya mguu wa ukurasa (ya juu)','Forbidden'=>'Kizuizi','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezimwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezuiwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Inalazimisha upya ramani ya tovuti wakati wa ombi lijalo. Tumia baada ya kuingiza kwa wingi au kuhariri kwa mikono uhusiano wa tafsiri.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Imepatikana {parts} kati ya <strong>{total}</strong> ya machapisho <strong>{scanned}</strong> yaliyopitiwa kwa <strong>{lang}</strong>.','From'=>'Kutoka','Front Page'=>'Ukurasa wa Mbele','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Uwezo wa FSE: tengeneza, tafsiri, na rekebisha viungo katika templates za Full Site Editing na sehemu za templates moja kwa moja kutoka kwa tab hii.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Mifano ya FSE iliyopandikizwa kutoka kwa mandhari hai. Unda kisha ibadilike kwenye Mhariri wa Tovuti.','Full'=>'Kamili','Full Article'=>'Makala Kamili','Full post'=>'Ujumbe kamili','General'=>'Jumla','Generate'=>'Tengeneza','Generate Content'=>'Tengeneza Yaliyomo','Generate content…'=>'Tengeneza maudhui…','Generate Excerpt'=>'Unda Kipengele','Generate Meta Description'=>'Unda Maelezo Meta','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Unda ramani ya lugha nyingi kwenye /lf-sitemap.xml','Generated Content'=>'Yaliyomo yaliyotengenezwa','Generated meta description'=>'Maelezo ya meta yaliyotengenezwa','Generating…'=>'Inazalishwa…','Generation failed.'=>'Uzalishaji umeshindwa.','Getting started'=>'Anza','Global AI preset'=>'Preset ya AI Ulimwenguni','Global default (%s)'=>'Chaguo-msingi duniani kote (%s)','Glossary'=>'Kamusi','Glossary entry added.'=>'Kuingiza kamusi ya msamiati kumetokea.','Glossary entry removed.'=>'Kufuta kamusi ya msamiati.','Glossary Tab'=>'Tabu ya Kamusi','Google (Gemini)'=>'Google (Gemini)','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Mode ya H2-kama-H1 imewezeshwa — kichwa kinahesabiwa kama sawa na H1. (Vichwa vinaweza kutotambuliwa kutoka kwa ukurasa uliotolewa; hakikisha mandhari yako inatoa kichwa kwa usahihi.)','Headings'=>'Vichwa vya habari','Hide'=>'Ficha','Hints'=>'Vidokezo','Home link text'=>'Maandishi ya kiungo cha nyumbani','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jinsi inapaswa kuonekana katika tafsiri. Andika thamani ile ile na neno la chanzo ili kuagiza AI kuilinda kwa maneno halisi.','How to use'=>'Jinsi ya kutumia','Hreflang'=>'Hreflang','Hreflang output'=>'Matokeo ya Hreflang','Hreflang settings saved.'=>'Mipangilio ya Hreflang imehifadhiwa.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Picha + lebo','Icon only'=>' Picha pekee','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ikiwa imeshakaguliwa, kufuta programu kutafuta kwa muda mrefu utafuta uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, mipangilio ya ukurasa, kamusi ya AI, na Kumbukumbu ya Tafsiri kwa kila chapisho kwenye tovuti hii. Hii haiwezi kurejeshwa. Acha ishiwi isipokuwa unatoa msaada wa lugha nyingi kutoka kwa tovuti.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Ikiwa una programu-jalizi ya SEO ya jumla iliyowekwa, jopo hili linaonyesha jinsi LF inavyobadilika ili kuepuka matokeo ya kurudiwa. Lengo ni kuepuka migongano — si ushirikiano. LF daima hutoa safu ya SEO ya lugha nyingi (hreflang, og:locale, inLanguage schema) inayohitaji ujuzi wa usanidi wa mwelekeo wa lugha wa LF ili kuzalisha kwa usahihi.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Ikiwa una SEO ya Yoast, Rank Math, All in One SEO, au SEOPress imewekwa, Lingua Forge huvitambua na kubadilika ili kuepuka matokeo ya kurudiwa. Kwa hreflang, LF inachukua udhibiti kabisa na kuzuia matokeo ya programu-jalizi kwa sababu programu-jalizi hizo haziwezi kuzalisha hreflang sahihi kwa usanidi wa mwelekeo wa lugha nyingi. Kwa Open Graph, LF huongeza tu og:locale na og:locale:alternate — ishara za lugha nyingi ambazo programu-jalizi haiwezi kutoa — na huacha seti ya OG ya msingi kwa programu-jalizi. Kwa Schema.org, LF huzimisha matokeo yake mwenyewe kabisa ili kuepuka michoro ya JSON-LD inayopingana.','Images'=>'Picha','Improve writing'=>'Boresha uandishi','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Katika mhariri wa kikundi, ongeza kikundi cha Ikoni za Kijamii. Kwa kila ikoni, fungua mipangilio ya kiungo na ingiza moja ya thamani za "share:" chini kama URL. Kwenye mbele, LF inabadilisha na URL sahihi ya kushiriki kwa ukurasa wa sasa.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Inajumuisha jina, maelezo, inLanguage, url, picha, na Ofa yenye bei, sarafu ya bei, na upatikanaji. Bei na upatikanaji vinatoka kwa bidhaa ya lugha asili (mfano wa hisa zinazoshirikishwa).','Includes site name, url, and inLanguage.'=>'Inajumuisha jina la tovuti, url, na inLanguage.','Informative'=>'Taarifa','Input tokens'=>'Token za ingizo','Install'=>'Sakinisha','Install a Language'=>'Sakinisha Lugha','Installed SEO plugins'=>'Programu-jalizi za SEO zilizowekwa','Installing…'=>'Inasakinishwa…','instock / oos / pending from WC stock status'=>'inashikilia / oos / inasubiri kutoka kwa hali ya hisa ya WC','Instructions (optional)'=>'Maagizo (hiari)','Instructions / key points'=>'Maagizo / vidokezo muhimu','Integration API'=>'API ya Uunganisho','Internal Link Fixer'=>'Rekebisha Kiungo cha Ndani','Introduction only'=>'Utangulizi tu','Invalid file reference.'=>'Rejea ya faili si sahihi.','Invalid filename.'=>'Jina la faili si sahihi.','Invalid language code.'=>'Msimbo batili wa lugha.','Invalid language.'=>'Lugha si sahihi.','Invalid locale code.'=>'Msimbo wa lugha si sahihi.','Invalid or primary language.'=>'Lugha si sahihi au ni kuu.','Invalid post ID.'=>'ID batili ya chapisho.','Invalid post type.'=>'Aina ya chapisho si sahihi.','Invalid template part.'=>'Sehemu ya kiolezo si sahihi.','Invalid template type.'=>'Aina ya kiolezo si sahihi.','JavaScript-powered actions'=>'Vitendo vinavyotegemea JavaScript','Key points, ideas, or structure to build from…'=>'Vitu muhimu, mawazo, au muundo wa kujenga kutoka...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Vifunguo vinahifadhiwa kwa usalama kwa AES-256-CBC kabla havijasomwa kwenye hifadhidata ya WordPress. Siri ya usimbuaji inatokana na chumvi za uthibitishaji wa WordPress (wp-config.php), kwa hivyo funguo za maandishi hayagusi hifadhidata kamwe.','Landing / Short-form'=>'Kuruka / Fomu fupi','Language'=>'Lugha','Language %s installed successfully.'=>'Lugha %s imewekwa kwa mafanikio.','Language (optional)'=>'Lugha (hiari)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Sakinisho la lugha limezimwa kwenye seva hii (DISALLOW_FILE_MODS imewekwa).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Sakinisho la lugha limezimwa kwenye seva hii. Kigezo cha DISALLOW_FILE_MODS kimewekwa katika wp-config.php. Sakinisha pakiti za lugha kwa mikono kupitia WP-CLI: wp language core install de_DE','Language label'=>'Lebo ya lugha','Language Overrides'=>'Mabadiliko ya Lugha','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Mabadiliko ya Lugha: simamia faili za mabadiliko maalum za .po/.mo kwa mistari ya UI ya Lingua Forge. Tumia hii badala ya kuhariri faili za programu moja kwa moja — mabadiliko yanadumu baada ya masasisho.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Sakinisho la pakiti ya lugha limegonga. Lugha inaweza tayari imewekwa, msimbo wa lugha si sahihi, au seva yako inazuia uandishi wa faili.','Language Setup'=>'Mipangilio ya Lugha','Language Switcher'=>'Kigeuzi cha Lugha','Language switcher'=>'Kisakinishi cha Lugha','Language uninstalled. %d post deleted.'=>'Lugha imeondolewa. Chapisho %d kimefutwa.' . "\0" . 'Lugha imeondolewa. Machapisho %d yamefutwa.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Nakili za lugha maalum za mandhari. Mara baada ya kuundwa, templates huboreshwa kurejelea sehemu maalum za lugha.','Language:'=>'Lugha:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Lugha zinazojulikana kwa sasa kwa router (zinatokana na pakiti za lugha za WordPress zilizowekwa pamoja na lugha kuu). Weka pakiti za lugha za ziada katika sehemu iliyo chini ili kufanya lugha zaidi zipatikane kwa uelekezaji na tafsiri.','Last 30 days'=>'Siku 30 zilizopita','Last 7 days'=>'Siku 7 zilizopita','Last generated: %s'=>'Imezalishwa mwisho: %s','Lead paragraph (≤60 w)'=>'Kipande cha kuongoza (≤60 w)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Acha uwanja wa mfano ukiwa tupu ili utumie chaguo-msingi cha ndani kwa kiwango hicho. Maandishi ya placeholder yanaonyesha mfano wa mfano utakaotumika.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Acha tupu kwa majina ya chapa na maneno yasiyotegemea lugha ambayo yanapaswa kutekelezwa bila kujali lugha tunayotafsiri kutoka.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Acha tupu ili kiingilio hiki kiweze kutumika kwa lugha zote za malengo — bora kwa majina ya chapa, kifupi, na maneno yanayopaswa kuhifadhiwa kwa maneno halisi katika kila tafsiri.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Acha tupu ili kuhifadhi funguo iliyopo. Ingiza thamani mpya kuibadilisha.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Acha tupu ili kutumia chaguo-msingi cha kujengwa ndani. Kufuta chaguo lililohifadhiwa kunarudisha chaguo-msingi wakati wa hifadhi inayofuata.','Legacy lf-social-share mu-plugin'=>'Mu-plugin wa zamani wa lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Mu-plugin wa zamani wa lf-social-share umegunduliwa. LF inahifadhi seti ya OG ya msingi kwa mu-plugin na inatoa og:locale + og:locale:alternate tu. Unaweza kuzima mu-plugin — Social Share iliyojengwa ndani ya LF (SEO → Social Share tab) na Cover ya Open Graph zinafanya kazi sawa.','Legal / Compliance'=>'Kisheria / Uzingatiaji','Legal / Compliance instructions'=>'Maagizo ya Kisheria / Uzingatiaji','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF daima huongeza og:locale na og:locale:alternate — ishara za lugha nyingi ambazo programu-jalizi haiwezi kuzalisha kwa usahihi. Kwa seti ya OG ya msingi (og:title, og:description, og:image), LF huitoa wakati hakuna programu-jalizi nyingine. Wakati programu-jalizi ya SEO imewekwa, LF huacha seti ya msingi ili kuepuka lebo za kurudiwa — si kwa sababu programu-jalizi ni "bora", bali kwa sababu kurudiwa hakutoa thamani.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF huunda ramani yake ya tovuti yenye viungo vya xhtml:link kwa vikundi vyote vya tafsiri. Wakati programu-jalizi ya SEO imewekwa, huunda ramani tofauti — zote zinashirikiana kwa uhuru. Wasilisha zote kwa Google Search Console: ramani ya tovuti ya programu-jalizi ya SEO kwa ugunduzi wa maudhui, ramani ya tovuti ya LF kwa ishara za uhusiano wa lugha.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF inatoa lebo za hreflang na imeondoa lebo ya canonical ya WordPress kwenye kurasa za lugha nyingi.','LF is suppressing hreflang output from: %s'=>'LF inazima matokeo ya hreflang kutoka: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF hutoa hreflang sahihi kwa kila lugha iliyowekwa, ikiwa ni pamoja na x-default. Vichungi vya SEO vya jumla havina ufikiaji wa usanidi wa LF routing na vingezalisha hreflang kulingana na dhihaka zisizo sahihi za URL. LF huzuia matokeo yao kupitia kichujio ili kuzuia migongano.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF hutoa JSON-LD yenye lugha nyingi na maelezo ya inLanguage yaliyoshikamana na usanidi wa routing wa lugha. Wakati plugin ya SEO imewekwa, LF huzimisha schema yake kabisa: michoro ya JSON-LD iliyojirudia huleta makosa ya uthibitishaji na hakuna njia safi ya kuongezea michoro iliyopo.','LF provides'=>'LF hutoa','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF huondoa tagi ya canonical ya WordPress kwenye kurasa za lugha nyingi kwa sababu sheria za kuandika upya za lugha za router na hreflang x-default ni ishara sahihi za canonical kwa tovuti yenye lugha nyingi. Hii huzuia canonical mara mbili ikiwa plugin ya SEO pia inatoa moja. LF haitoi canonical yake mwenyewe — routing ya lugha tayari hufanya kila URL kuwa canonical.','Light'=>'Nuru','Light (default — fast and cost-effective)'=>'Nuru (chaguo-msingi — haraka na yenye gharama nafuu)','Light (fast and cost-effective — Haiku / Flash)'=>'Mwanga (haraka na nafuu — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Nuru: inatumika kwa maelezo mafupi na uzalishaji wa excerpt — haraka, gharama ya chini.','Limit results to pages in the given Lingua Forge language code.'=>'Lenga matokeo kwa kurasa zilizo katika msimbo wa lugha wa Lingua Forge uliotolewa.','Limits'=>'Mipaka','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge huongeza mwelekeo wa lugha nyingi, tafsiri yenye nguvu ya AI, tags za SEO za hreflang, na kisakinishi cha lugha kwenye tovuti yako ya WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge huongeza mali za Open Graph maalum za WooCommerce kwenye kurasa za bidhaa ili kushiriki URL ya bidhaa kwenye Facebook, Pinterest, na majukwaa mengine kuonyesha aina sahihi ya bidhaa, bei, na upatikanaji.','Lingua Forge AI Tools'=>'Vifaa vya Lingua Forge AI','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge huongeza bloki la Ikoni za Kijamii za WordPress Core na URLs za kushiriki za mabadiliko. Weka kiungo cha ikoni yoyote kwa thamani ya "share:" na LF huandika upya kuwa URL sahihi ya kushiriki au kitendo cha JavaScript wakati wa kuonyesha — hakuna msimbo maalum au plugin ya watu wa tatu inayohitajika.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge hutoa ramani ya tovuti ya XML iliyojitenga kwenye /lf-sitemap.xml ambayo huongeza viungo vya lugha mbadala kwa maudhui yako yote yaliyotafsiriwa. Ramani hii ya tovuti inaambatana na ramani ya tovuti ya WordPress na ramani ya tovuti ya plugin yoyote ya SEO — haitabadilishi.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge ni suluhisho kamili la SEO lenye lugha nyingi. Hakuna plugin ya SEO ya ziada inayohitajika.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge ni suluhisho kamili la SEO lenye lugha nyingi. Hakuna plugin ya SEO au ramani ya tovuti inayohitajika.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge hutoa lebo za <link rel="alternate" hreflang> kwa kila lugha iliyowekwa kwenye kila ukurasa, ikijumuisha x-default inayorejelea lugha ya chanzo. Hii ni ishara kuu ya SEO ya lugha nyingi kwa Google na injini nyingine za utafutaji — hakuna kiambatanisho cha SEO cha ziada kinachohitajika.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge hutoa meta tags za Open Graph na Twitter Card ili URLs zilizoshirikiwa zionyeshe lugha sahihi, kichwa, maelezo, na picha kwenye majukwaa ya kijamii.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge hutoa data iliyopangwa ya Schema.org JSON-LD ili injini za utafutaji kuelewa aina ya maudhui yako, lugha, na metadata. Hii ndiyo njia kuu ya kuwasiliana maelezo ya inLanguage kwa Google na wakusanyaji wengine.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge inazuia vipengele viwili vya Gutenberg kwa chaguo-msingi ili kuweka tabia ya uhariri kuwa thabiti kati ya lugha. Chagua hapa ikiwa unahitaji uwezo kamili wa Gutenberg / FSE.','Lingua Forge Settings'=>'Mipangilio ya Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge hutumia safu mbili za cache huru ili kuepuka kuita API za AI mara kwa mara. Tumia vivinjari hapa chini kuangalia na kusimamia kila moja.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge hutumia safu mbili za mfano kwa kila mtoa huduma:','Lingua Forge — Quick Translate'=>'Lingua Forge — Tafsiri Haraka','Lingua Forge — Settings'=>'Lingua Forge — Mipangilio','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Modules za Kushiriki Kijamii na Open Graph zilizojengwa ndani ya Lingua Forge zinashughulikia kazi zote zinazotolewa na mu-plugin, pamoja na msaada wa og:locale wa lugha nyingi. Unaweza kuzima salama mu-plugin.','Link copied'=>'Kiungo kime nakiliwa','link(s)'=>'kiungo(viungo)','Links'=>'Viungo','Load available languages'=>'Pakua lugha zinazopatikana','Load content'=>'Pakia maudhui','Loaded from cache.'=>'Imepakuliwa kutoka kwa cache.','Loading…'=>'Inapakia…','Locale only'=>'Lugha pekee','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Imefungwa — plugin ya SEO inayopingana iko hai. Tazama arifa hapo juu.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate hifadhi tafsiri zake maalum katika wp-content/languages/loco/ — mahali ambapo inaweza kufutwa kwa kimya na sasisho la WP, kufanywa upya kwa programu, au ikiwa Loco Translate yenyewe inatoweka. Nakili faili hapa huziweka kwenye saraka ya Lingua Forge i18n-overrides, ambayo huendelea kuwa hai kupitia matukio yote hayo na hujumuishwa kiotomatiki kila wakati.','Loco Translate — Copy to Safe Storage'=>'Loco Tafsiri — Nakili kwa Hifadhi Salama','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Uwezo wa WordPress wa chini kabisa unaoruhusiwa kuanzisha vipengele vya AI. Kuimarisha hili kwenye tovuti za waandishi wengi kunazuia Wachangia au akaunti za majaribio kuendesha simu za AI zilipwa. Pitia kwa kila kipengele kupitia kichujio cha "linguaforge_required_capability".','Maintenance'=>'Matengenezo','Maintenance Tab'=>'Tabu ya Matengenezo','Make casual'=>'Fanya kwa kawaida','Make concise'=>'Fupisha','Make formal'=>'Fanya rasmi','Mark citations needed'=>'Alama za kuashiria mahitaji ya nukuu','Max context characters'=>'Wahusika wa muktadha wa juu zaidi','Max hints characters'=>'Wahusika wa vidokezo vya juu zaidi','Max input characters'=>'Herufi za ingizo za juu zaidi','Max output tokens'=>'Idadi ya tokeni za matokeo makubwa','Maximum characters accepted from the input field. Default: 8 000.'=>'Wahusika wa juu zaidi wanaokubaliwa kutoka kwa uwanja wa ingizo. Chaguo-msingi: 8,000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Wahusika wa juu zaidi wa maudhui ya chapisho yaliyopo yanayotumwa kwa AI kama muktadha wa mbegu wakati hakuna Vidokezo vinavyotolewa. Chaguo-msingi: 6,000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Wahusika wa juu zaidi wanaosomwa kutoka kwa uwanja wa Vidokezo. Chaguo-msingi: 2,000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Kiwango kikubwa cha wahusika wa maudhui ya chapisho yaliyotumwa kwa AI. 0 inamaanisha hakuna kikomo — maudhui kamili yanatumiwa daima (inapendekezwa). Weka thamani isiyo sifuri ikiwa mtoa huduma wako ana dirisha la muktadha mkali. Onyo linaandikwa kwenye kumbukumbu ya makosa ya PHP kila wakati maudhui yanapunguzwa.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Idadi kubwa ya tokeni ambazo AI inaweza kuzalisha kwa jibu moja la tafsiri. Ikiwa tafsiri inakatwa kimya kimya mwisho, ongeza thamani hii. Chaguo-msingi: 16,000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Wahusika wa juu zaidi wanaowezekana na AI wanaweza kuzalisha kwa kila uendeshaji wa kizazi. Ongeza ikiwa makala kamili yanakatwa. Chaguo-msingi: 8,192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Wahusika wa juu zaidi wanaowezekana na AI inaweza kuzalisha kwa kila tafsiri ya haraka. Chagua: 2,000.','Meta Description'=>'Maelezo ya Meta','Meta description'=>'Maelezo ya meta','Meta Description, Excerpt Generator'=>'Maelezo ya Meta, Mwandishi wa Muhtasari','Metric'=>'Kiwango','Minimum role'=>'Hali ya chini','Missing pattern name or language.'=>'Jina la muundo au lugha inakosekana.','Mode'=>'Hali','Model'=>'Mfano','Model tier'=>'Kiwango cha mfano','Models'=>'Miundo','Models Tab (General)'=>'Tabu ya Mifano (Kwa Jumla)','Modified'=>'Imebadilishwa','Most recent cached block'=>'Blokii ya hivi karibuni iliyohifadhiwa','Most recent cached response'=>'Majibu ya hivi karibuni yaliyohifadhiwa','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Njia za lugha nyingi, SEO kamili ya lugha nyingi (hreflang, Open Graph, Schema.org, ramani ya tovuti), na zana za AI za maudhui kwa WordPress. Utambuzi wa lugha, njia za URL, tafsiri, uzalishaji wa maudhui, na safu kamili ya SEO — hakuna programu-jalizi ya msaidizi inayohitajika.','Name displayed in this language. Leave empty to use the source name.'=>'Jina linaloonyeshwa kwa lugha hii. Acha tupu ili kutumia jina la chanzo.','Navigation'=>'Urambazaji','Navigation has no content to translate.'=>'Uelekeo haujakuwa na maudhui ya kutafsiri.','Navigation not found.'=>'Uelekeo haujapatikana.','Navigation posts are translated via the Router tab, not this button.'=>'Maandishi ya urambazaji yanatafsiriwa kupitia kichupo cha Router, si kitufe hiki.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Utaratibu wa urambazaji unahitaji mtoa huduma wa AI anayeishi. Sanidi ufunguo wa API kwenye kichupo cha Funguo za API.','Navigations'=>'Viongozi','Network error — could not reach the WordPress AJAX endpoint.'=>'Hitilafu ya mtandao — haikuweza kufikia mwisho wa AJAX wa WordPress.','No %s version found in this translation group.'=>'Hakuna toleo la %s lililopatikana katika kundi hili la tafsiri.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Hakuna hatua inayohitajika. Google ilizindua mwisho wa endpoint yake ya sitemap ping mwezi Januari 2024 na sasa huagiza ramani za tovuti pekee kupitia amri ya robots.txt Sitemap: — ambayo LF tayari imepanga. Google itachukua kwenye utafutaji wake ujao.','No AI provider configured.'=>'Mtoa huduma wa AI hajaanzishwa.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Hakuna mtoa huduma wa AI aliyepangwa. Ongeza ufunguo wa API katika Mipangilio → Funguo za API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Hakuna matumizi ya AI yaliyorekodiwa katika dirisha lililochaguliwa (%s). Chagua wingi zaidi juu.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Hakuna matumizi ya AI yaliyorekodiwa bado. Mara editor anapofanya tafsiri, kuunda maelezo ya meta, au kutumia kipengele kingine cha AI, jumla zitajitokeza hapa.','No API key configured for this provider.'=>'Hakuna funguo ya API iliyowekwa kwa mtoa huduma huu.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Hakuna maagizo yaliyowekwa ndani — kila kipengele cha AI kinatumia chaguo zake zilizobinafsishwa. Jaza uwanja wa Maagizo ya Maelekezo ya Maoni ya Kibinafsi hapa chini ili kuongeza kanuni zako za tovuti kwa ujumla.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Hakuna plugins za SEO zinazopingana zilizogunduliwa. Lingua Forge inashughulikia matokeo yote ya SEO kwa uhuru.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Hakuna faili maalum za Loco Translate bado. Zinaonekana hapa mara tu unapohifadhi tafsiri kwenye Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Hakuna plugin ya OG ya nje iliyogunduliwa. LF inatoa seti kamili ya OG + Twitter Card.','No file was selected.'=>'Hakuna faili iliyochaguliwa.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Hakuna viingilio vya kamusi vinavyolingana na kichujio cha sasa. Futa kichujio ili kuona viingilio vyote, au ongeza kiingilio kipya chini.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Hakuna viingilio vya kamusi bado. Weka chini ili kuanza kutekeleza istilahi katika tafsiri.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Hakuna H1 iliyopatikana. Kawaida kichwa cha chapisho ni H1 — hakikisha mandhari yako inachapisha hicho.','No images found in content.'=>'Hakuna picha zilizopatikana kwenye maudhui.','No internal links found to update.'=>'Hakuna viungo vya ndani vilivyopatikana vya kusasisha.','No language-specific template parts found to map.'=>'Hakuna sehemu za kiolezo zinazohitajika kubadilishwa ili kuoanisha.','No LF meta description set — using excerpt/content.'=>'Hakuna maelezo ya meta ya LF yaliowekwa — inatumia excerpt/maudhui.','No links found.'=>'Hakuna viungo vilivyopatikana.','No links found. Internal links improve crawlability and user navigation.'=>'Hakuna viungo vilivyopatikana. Viungo vya ndani vinaboresha utafutaji na urambazaji wa mtumiaji.','No meta description found. Generate one via the AI meta description feature.'=>'Hakuna maelezo ya meta yaliyopatikana. Tengeneza moja kwa kutumia kipengele cha AI cha maelezo ya meta.','No navigation references needed updating.'=>'Hakuna marejeo ya urambazaji yanayohitajika kusasishwa.','No override files uploaded yet.'=>'Hakuna faili za mabadiliko zilizopakiwa bado.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Hakuna faili halali ya robots.txt iliyopatikana. WordPress inazalisha kwa njia ya mtandao na amri ya Sitemap ya LF imejumuishwa kiatomati.','No published posts found for the selected filters.'=>'Hakuna machapisho yaliyochapwa yaliyopatikana kwa vichujio vilivyoteuliwa.','No response from AI provider. Check your API key and try again.'=>'Hakuna majibu kutoka kwa mtoa huduma wa AI. Angalia ufunguo wako wa API na jaribu tena.','No response from provider — check the error log for details.'=>'Hakuna majibu kutoka kwa mtoa huduma — angalia kumbukumbu za makosa kwa maelezo.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Hakuna lugha za ziada zilizowekwa. Sakinisha pakiti ya lugha hapo juu ili kuwezesha muundo wa kiolezo.','No source content found to translate.'=>'Hakuna maudhui ya chanzo yaliyopatikana ya kutafsiri.','No source page linked yet.'=>'Bado hakuna ukurasa wa chanzo umeunganishwa.','No template part references needed updating.'=>'Hakuna marejeo ya sehemu za kiolezo zinazohitajika kusasishwa.','No title set.'=>'Hakuna kichwa kilichowekwa.','No translated content found. The sitemap will populate once posts have been translated.'=>'Hakuna maudhui yaliyotafsiriwa yaliyopatikana. Ramani ya tovuti itajaa mara baada ya machapisho kutafsiriwa.','No translation found — analyzed the source language version.'=>'Hakuna tafsiri iliyopatikana — ilitathmini toleo la lugha asili.','No {lang} translation registered (TRID missing)'=>'Hakuna tafsiri ya {lang} iliyosajiliwa (TRID inakosekana)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Bado haijatengenezwa. Ramani ya tovuti hujengwa kwenye ziara ya kwanza kwenye URL ya ramani ya tovuti na huhifadhiwa kwa masaa 24.','Notes'=>'Maelezo','Nothing — all types disabled'=>'Hakuna kitu — aina zote zimezimwa','Notice message'=>'Ujumbe wa arifa','Notice settings'=>'Mipangilio ya arifa','Notify search engines'=>'Arifu injini za utafutaji','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Vichwa vya OG/Twitter Card: vinashughulikiwa na moduli ya Open Graph ya LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Blokii ya zamani zaidi iliyohifadhiwa','Oldest cached response'=>'Majibu ya zamani zaidi yaliyohifadhiwa','Only .mo files are accepted.'=>'Faili za .mo pekee zinakubaliwa.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Kadi za Open Graph &amp; Twitter','Open Graph output'=>'Utoaji wa Open Graph','Open Graph settings saved.'=>'Mipangilio ya Open Graph imehifadhiwa.','Open Search Console →'=>'Fungua Google Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Fungua karatasi ya kushiriki ya wavuti ya asili ya simu (iOS, Android, baadhi ya kompyuta). Inarudiwa kwa nakala kwenye ubao wa kunakili ikiwa haipo.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Muktadha wa hiari kwa wahariri (kama vile "ASIC = Circuit ya Maombi Mahususi; ihifadhi kwa Kiingereza katika muktadha wa kiufundi").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Hiari. Bing tayari inasoma amri ya Sitemap: kutoka kwa robots.txt — hii inasababisha upya wa haraka badala ya kusubiri ukaguzi ujao wa ratiba.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Hiari. Yandex tayari inasoma amri ya Sitemap: kutoka kwa robots.txt — hii inasababisha upya wa haraka badala ya kusubiri ukaguzi ujao wa ratiba.','Output'=>'Matokeo','Output Article or WebPage schema on singular posts and pages'=>'Toa schema ya Article au WebPage kwenye machapisho na kurasa za pekee','Output hreflang tags in wp_head'=>'Toa lebo za hreflang kwenye wp_head','Output mode'=>'Njia ya kutoa','Output Open Graph tags in wp_head'=>'Toa lebo za Open Graph kwenye wp_head','Output Product schema on WooCommerce product pages'=>'Toa schema ya Product kwenye kurasa za bidhaa za WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Muundo wa JSON-LD wa Schema.org wa pato katika wp_head','Output tokens'=>'Token za matokeo','Output WebSite schema on the front page and blog index'=>'Toa muundo wa WebSite kwenye ukurasa wa mbele na orodha ya blogu','Overall SEO score'=>'Alama ya jumla ya SEO','overridden'=>'kimezuiwa','Override file deleted.'=>'Faili ya mabadiliko imefutwa.','Override file uploaded successfully.'=>'Faili ya mabadiliko imepakuliwa kwa mafanikio.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Vipengele vingine vyote vinatumia mipangilio ya jumla kila wakati.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Maagizo ya maoni maalum ya tovuti yote (Mipangilio → Tabia) yanajumuishwa kila wakati kwenye kila ombi bila kujali chaguo hili.','Overview'=>'Muhtasari','Page'=>'Ukurasa','Part'=>'Sehemu','Paste a footnote, sentence, or any snippet here…'=>'Bandika nukuu ya mguu wa ukurasa, sentensi, au kipande chochote hapa...','Paste text, or select text in the editor first…'=>'Bandika maandishi, au chagua maandishi kwenye mhariri kwanza…','Paste text, or select text on the page first…'=>'Bandika maandishi, au chagua maandishi kwenye ukurasa kwanza…','Paste your API key…'=>'Bandika funguo lako la API…','Path prefix — example.com/de/'=>'Kipindi cha njia — example.com/de/','Pattern'=>'Mfano','Pattern has no content to translate.'=>'Muundo haujashikilia maudhui ya kutafsiriwa.','Pattern not found.'=>'Muundo haujapatikana.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muundo umetafsiriwa na kuhifadhiwa. Nakili maudhui kwenye chapisho lako la CPT kupitia mhariri wa kiolezo au tumia kama mwanzo wa Kiolezo kinachoweza kutumika tena.','Pattern translation failed.'=>'Ufasirishwa kwa mfano umeshindwa.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Kuhifadhi kwa kila chapisho kwa ajili ya tafsiri zinazotolewa na AI, maelezo ya meta, muhtasari, na maudhui. Daima inafanya kazi — hakuna kitufe tofauti kinachohitajika. Viingilio vinavunjwa kiotomatiki wakati maudhui au mtoaji/model wa AI unabadilika.','Permalink rules flushed successfully.'=>'Sheri za permalink zimefutwa kwa mafanikio.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Futa kwa kudumu mifano yote, sehemu za mifano, mifano, menyu za urambazaji, machapisho, kurasa, aina maalum za machapisho, bidhaa, na mabadiliko ya bidhaa yanayohusiana na lugha hii. Pia huondoa faili za pakiti za lugha ya WordPress ili lugha hii isiweze kuonekana tena kwenye router. Hatua hii haiwezi kurudishwa nyuma.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Futa kwa kudumu %s? Hii itafuta maudhui yote yaliyotafsiriwa kwa lugha hii na haiwezi kurudishwa nyuma.','Permission denied.'=>'Ruhusa imekatwa.','Persuasive'=>'Ushawishi','PHP constant'=>'kifungo cha PHP','Pin on Pinterest'=>'Bonyeza kwenye Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Weka maneno ambayo hayapaswi kutafsiriwa au lazima yatangazwe kwa njia fulani (k.m. majina ya chapa, majina ya bidhaa, maneno mafupi). Mipaka ya kamusi huingizwa katika kila ombi la tafsiri la AI kwa ajili ya vipengele vyote: tafsiri ya chapisho, maelezo ya meta, excerpt, na tafsiri ya template ya FSE.','Ping Bing'=>'Pinga Bing','Ping Yandex'=>'Pinga Yandex','Plain language'=>'Lugha rahisi','Please enter some instructions first…'=>'Tafadhali ingiza maagizo kwanza…','Please enter some text first…'=>'Tafadhali ingiza maandishi kwanza…','Plugin'=>'Programu-jalizi','Post'=>'Uchapishaji','Post not found or not published.'=>'Chapisho hakipatikani au hakijachapishwa.','Post not found.'=>'Chapisho hakipatikani.','Post on X / Twitter'=>'Chapisho kwenye X / Twitter','Post Types'=>'Aina za Machapisho','Prefilled from excerpt. Edit to override.'=>'Imejazwa kutoka kwa muhtasari. Badilisha ili kuizidi.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Bei na upatikanaji daima huonyesha bidhaa ya lugha asili (mfano wa hisa zinazoshirikishwa). Vitambulisho huonyeshwa tu wakati moduli ya Open Graph ya LF imewekwa kwa "Full" au "Auto" bila programu-jalizi ya SEO inayopingwa.','Primary Language'=>'Lugha Kuu','Primary language'=>'Lugha kuu','Primary language saved.'=>'Lugha kuu imehifadhiwa.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Lugha kuu: lugha ambayo maudhui yako ya sasa yameandikwa. Tafsiri zote hutoka kwa lugha hii; kubadilisha hakusababishi kuhamisha au kufuta machapisho yoyote.','Processing…'=>'Inashughulikiwa…','Product'=>'Bidhaa','Product / eCommerce'=>'Bidhaa / eCommerce','Product Open Graph'=>'Open Graph ya Bidhaa','Product — WooCommerce product pages'=>'Bidhaa — kurasa za bidhaa za WooCommerce','Profile'=>'Wasifu','Provider'=>'Mtoa huduma','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Mtoa huduma haukutoa maandishi. Angalia kumbukumbu za makosa za WordPress kwa sababu kamili ya kushindwa.','Quality'=>'Ubora','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (chaguo-msingi — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Ubora: hutumika kwa tafsiri ya chapisho na uzalishaji wa maudhui — ubora wa juu, gharama ya juu.','Quick Translate'=>'Tafsiri Haraka','Quick Translation'=>'Tafsiri Haraka','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Tafsiri Haraka hutumiwa kwa hali ya vipande/vipande — vifungu vifupi vinavyotafsiriwa kwa ombi kutoka kwa upau wa zana, mhariri, au popo za kizuizi. Inatumia usanidi tofauti, nyepesi kutoka kwa tafsiri ya ukurasa kamili ili kuweka majibu kuwa ya haraka na yenye gharama nafuu.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Inarudisha tena Gutenberg\'s canLockBlocks. Inafaa kwa templates za uhariri zinazohitaji kuzuia wachangiaji kuhamisha au kufuta blocks fulani.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Inarudisha tena supportsTemplateMode. Muhimili kwa mchakato wa Uhariri wa Tovuti Kamili ambapo ubadilishaji wa template wa kiwango cha chapisho ni nia.','Re-generates and updates the cached result.'=>'Inazalisha tena na kusasisha matokeo yaliyohifadhiwa.','Re-scan'=>'Re-scan','Re-scanning…'=>'Inasoma tena...','Re-translate'=>'Tafsiri tena','Reading time'=>'Muda wa kusoma','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Uelekeza wageni kwa lugha yao wanayoipendelea kulingana na kichwa cha Accept-Language cha kivinjari','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Boresha zaidi — mfano "fupisha" au "tumia sauti rasmi"…','Refine further:'=>'Boresha zaidi:','Refinement'=>'Uainishaji','Refinement failed — please try again.'=>'Uainishaji umeshindwa — tafadhali jaribu tena.','Refining…'=>'Inasafishwa…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Inarejesha sheria za uandishi wa WordPress ili viambishi vya URL, slug za lugha, na uandishi wa makala viwe vinaendana. Inahitajika baada ya kubadilisha lugha kuu au kuongeza msaada wa lugha mpya.','Remove stored key'=>'Ondoa funguo iliyohifadhiwa','Report an issue on GitHub'=>'Ripoti tatizo kwenye GitHub','Request failed — please try again.'=>'Ombi limekosewa — tafadhali jaribu tena.','Request failed.'=>'Ombi limekosewa.','Request failed. Check your connection.'=>'Ombi limeshindwa. Angalia muunganisho wako.','Request failed. Please try again.'=>'Ombi limeshindwa. Tafadhali jaribu tena.','Requests'=>'Maombi','Reset'=>'Washa upya','Result will appear here…'=>'Matokeo yataonekana hapa…','Retranslate'=>'Tafsiri tena','Retranslating…'=>'Inatafsiri tena…','Review carefully — links and slugs not updated.'=>'Kagua kwa makini — viungo na slugs havijasasishwa.','Review translation before applying'=>'Kagua tafsiri kabla ya kutumia','Revise'=>'Rekebisha','Revision'=>'Uboreshaji','Revision Type'=>'Aina ya Uboreshaji','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt imesasishwa na maagizo ya Ramani ya Tovuti.','Router'=>'Router','Router Tab'=>'Tabu ya Router','Run AI Analysis'=>'Endesha Uchanganuzi wa AI','Save analysis settings'=>'Hifadhi mipangilio ya uchambuzi','Save Debug Setting'=>'Hifadhi Mipangilio ya Kagua','Save Hreflang Settings'=>'Hifadhi Mipangilio ya Hreflang','Save Open Graph Settings'=>'Hifadhi Mipangilio ya Open Graph','Save Router Settings'=>'Hifadhi Mipangilio ya Router','Save Schema.org Settings'=>'Hifadhi Mipangilio ya Schema.org','Save Settings'=>'Hifadhi Mipangilio','Save Sitemap Settings'=>'Hifadhi Mipangilio ya Ramani ya Tovuti','Save Social Share Settings'=>'Hifadhi Mipangilio ya Shiriki Kijamii','Save the post to persist changes.'=>'Hifadhi chapisho ili kudumisha mabadiliko.','Save Uninstall Setting'=>'Hifadhi Mipangilio ya Kufuta','Save WooCommerce SEO Settings'=>'Hifadhi Mipangilio ya SEO ya WooCommerce','Saved to the meta description field when you apply.'=>'Imehifadhiwa kwenye uwanja wa maelezo ya meta unapoomba.','Scan failed: '=>'Uchunguzi umeshindwa: ','Scan request failed. Please try again.'=>'Ombi la uchunguzi limekosa mafanikio. Tafadhali jaribu tena.','Scanning posts for broken language links…'=>'Inasoma machapisho kwa ajili ya viungo vya lugha vilivyovunjika...','Schema output deferred.'=>'Matokeo ya Schema yameahirishwa.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD ya Schema.org','Schema.org output'=>'Matokeo ya Schema.org','Schema.org settings saved.'=>'Mipangilio ya Schema.org yamehifadhiwa.','Search'=>'Tafuta','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Kituo cha Utafutaji ni muhimu kwa kufuatilia makosa ya uandikishaji na ufunikaji, lakini si lazima kwa ugunduzi.','Search Results'=>'Matokeo ya Utafutaji','Security check failed — file path is not permitted.'=>'Uhakiki wa usalama umeshindwa — njia ya faili haikubaliki.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Chagua lugha ili kuendesha muundo wa FSE, sehemu za muundo, na menyu za urambazaji.','Select language'=>'Chagua lugha','Send via Telegram'=>'Tuma kupitia Telegram','Send via WhatsApp'=>'Tuma kupitia WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Uchambuzi wa SEO','SEO character-count info'=>'Habari za idadi ya wahusika za SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Programu-jalizi(zi) za SEO zilizogunduliwa: %s. LF inatoa og:locale na og:locale:alternate pekee; programu-jalizi iliyogunduliwa inashughulikia seti kamili ya OG.','SEO plugins and conflict avoidance:'=>'Programu-jalizi za SEO na kuepuka migongano:','SEO Tab'=>'Kipengele cha SEO','Server setup (subdomain)'=>'Mipangilio ya seva (subdomain)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Huweka tabia chaguo-msingi ya AI kwa vipengele vyote vya tovuti. Chapisho binafsi kinaweza kubadilisha hii kwa Tafsiri na Uundaji wa Maudhui kupitia sanduku la meta la Lingua Forge.','Settings'=>'Mipangilio','Settings saved.'=>'Mipangilio imehifadhiwa.','Share on Facebook'=>'Shiriki kwenye Facebook','Share on LinkedIn'=>'Shiriki kwenye LinkedIn','Share on Mastodon'=>'Shiriki kwenye Mastodon','Share via email (mailto:)'=>'Shiriki kupitia barua pepe (mailto:)','Show home link'=>'Onyesha kiungo cha nyumbani','Shown when no translation exists for the visitor\'s language.'=>'Unaonyeshwa wakati hakuna tafsiri inayopo kwa lugha ya mgeni.','Single'=>'Moja','Single %s'=>'Moja %s','Single: %s'=>'Moja: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Kikomo cha tovuti kwa maombi ya AI kwa siku ya UTC (kinahesabu tafsiri za Zana na marekebisho ya kizuizi). Kiwango kinarejeshwa saa sita usiku wa UTC. Weka 0 ili kuzima kikomo.','Sitemap'=>'Ramani ya Tovuti','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Hifadhi ya Ramani ya Tovuti imefutwa. Itatengenezwa tena wakati wa ziara inayofuata kwenye URL ya ramani ya tovuti.','Sitemap output'=>'Matokeo ya Ramani ya Tovuti','Sitemap settings saved.'=>'Mipangilio ya Ramani ya Tovuti yamehifadhiwa.','Sitemap URL'=>'URL ya Ramani ya Tovuti','Size'=>'Ukubwa','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Shiriki wa blok ya Ikoni za Kijamii: URLs: zinashughulikiwa na Shirikisho la Kijamii la LF lililojengwa ndani (SEO → Kushiriki Kijamii)','Social Share'=>'Shiriki Kijamii','Social Share settings saved.'=>'Mipangilio ya Shiriki la Kijamii yamehifadhiwa.','Some link fixes failed.'=>'Baadhi ya marekebisho ya viungo yameshindwa.','Some nav ref fixes failed.'=>'Marekebisho ya marejeo ya urambazaji yameshindwa.','Some part fixes failed.'=>'Sehemu zingine hazikuweza kurekebishwa.','Some parts could not be created.'=>'Sehemu zingine hazikuweza kuundwa.','Some templates could not be created.'=>'Baadhi ya kiolezo hakikuweza kuundwa.','Some translations failed.'=>'Baadhi ya tafsiri zimeshindwa.','source'=>'chanzo','Source file not found.'=>'Faili ya chanzo haipatikani.','Source lang'=>'Lugha ya Chanzo','Source language'=>'Lugha ya Chanzo','Source term'=>'Neno la Chanzo','Standard'=>'Kawaida','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Kawaida hutumia joto la kila kipengele kilichopimwa: Tafsiri T=0.2 (sahihi), Tafsiri Haraka T=0.4, Mwandishi wa Maudhui T=0.6 (ubunifu). Preset nyingine hutumia joto moja lililowekwa kwa vipengele vyote.','Status'=>'Hali','Status / Actions'=>'Hali / Vitendo','Storytelling'=>'Hadithi','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Hali kali ya uhifadhi kwa maudhui ya kisheria, kanuni, matibabu, au ya kiufundi. Wakati iko, kila kipengele cha AI kinatumia joto la sampuli ya chini na huongeza kifungu cha chini kwa amri ya mfumo — istilahi, nambari za makala, vitengo, majina ya chapa, na lugha za kanuni huhifadhiwa verbatim badala ya kufupishwa.','Structured Outline'=>'Muhtasari wa Muundo','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode ya subdomain inahitaji seva yako ya wavuti kuelekeza subdomains zote za lugha (kama de.example.com) kwa usakinishaji huu wa WordPress. Baada ya kubadilisha mode, fanya usafi wa sheria za permalink na safisha cache yoyote. Ikiwa URL yako ya nyumbani inajumuisha www (kama www.example.com), tumia kichujio cha lf_base_domain kuweka domain kuu bila www ili subdomains zifanywe kwa usahihi.','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Wasilisha URL hii kwa Google Search Console pamoja na ramani yako kuu ya tovuti.','Submit to Reddit'=>'Wasilisha kwa Reddit','Suggested meta description'=>'Maelezo ya meta yaliyopendekezwa','Suggested title'=>'Kichwa cha pendekezo','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Watoa huduma wanaotegemewa: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Mtoa huduma mmoja tu anafanya kazi kwa wakati mmoja. Chagua mtoa huduma anayeendelea kwenye tabu ya Jumla.','Suppressed: %s.'=>'Imesimamishwa: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, kwa kila kipengele','Tag'=>' Lebo','Tags emitted'=>'Lebo zilizotolewa','Target lang'=>'Lugha ya Malengo','Target Language'=>'Lugha inayolengwa','Target language'=>'Lugha ya Malengo','Target term'=>'Neno la Malengo','Target: 140–160 chars for optimal SERP display'=>'Lengo: wahusika 140–160 kwa kuonyesha bora kwenye SERP','Technical'=>'Kitaaluma','Technical / Scientific'=>'Kitaaluma / Sayansi','Technical / Scientific instructions'=>'Maagizo ya Kiufundi / Sayansi','Template "%s" already exists.'=>'Kiolezo "%s" tayari kipo.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Kiolezo "{expected}" hakipo — tengeneza kwanza kwenye Mhariri wa Tovuti.','Template has no content.'=>'Kiolezo hakina maudhui.','Template mode'=>'Hali ya template','Template not found or not stored in the database.'=>'Kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template part "%s" already exists.'=>'Sehemu ya kiolezo "%s" tayari kipo.','Template part has no content.'=>'Sehemu ya kiolezo hakina maudhui.','Template part not found or not stored in the database.'=>'Sehemu ya kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template Parts'=>'Sehemu za Muundo','Templates'=>'Mifano','Test connection'=>'Jaribu muunganisho','Testing…'=>'Inajaribu…','Text domain / locale'=>'Uwanja wa lugha / muktadha','Text to translate'=>'Maandishi ya kutafsiri','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Cache ya Majibu ya API hifadhi matokeo halisi ya kila ombi la AI — tafsiri, maelezo ya meta, excerpt, na uzalishaji wa maudhui — kwa kutumia hash ya maingizo (maudhui, jozi ya lugha, mtoa huduma, mfano). Maombi yanayofuata yenye maingizo sawa yanatumikia kutoka kwa cache bila kuita API. Cache hii ni tofauti na Kumbukumbu ya Tafsiri: Kumbukumbu ya Tafsiri hufanya kazi kwa kiwango cha blokii na inashirikiana kati ya machapisho; Cache ya Majibu ya API hufanya kazi kwa kiwango cha kipengele na inahifadhiwa kwa kila chapisho.','The editor did not accept the content — please try again.'=>'Mhariri hakukubali maudhui — tafadhali jaribu tena.','The following directive is active in your virtual robots.txt:'=>'Agizo lifuatalo ni hai katika robots.txt yako ya mtandao:','The lf-social-share mu-plugin is active.'=>'Mu- plugin wa lf-social-share ni hai.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Mu- plugin wa lf-social-share ni hai. Social Share iliyojengwa ndani ya Lingua Forge haifanyi kazi — mu-plugin inashughulikia uandishi upya wa URL za kushiriki na vitendo vya JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Kiwango cha Nuru kinatumia mfano wa haraka uliowekwa kwenye jedwali la Miundo hapo juu (chaguo-msingi: Haiku / Flash). Badilisha kwa Ubora ikiwa unahitaji usahihi wa tafsiri sawa na hali ya ukurasa kamili kwa vipande.','The phrase as it appears in the source text.'=>'Sehemu kama ilivyoonekana katika maandishi ya chanzo.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Lugha kuu daima hutumika kwenye mzizi wa tovuti yako — hakuna kiambishi cha URL katika hali ya njia, hakuna subdomain ya lugha katika hali ya subdomain. Lugha nyingine zote hutumia au kiambishi cha /lang/ (mfano example.com/de/) au subdomain ya lugha (mfano de.example.com), kulingana na mpangilio wa muundo wa URL hapo chini.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Kipengele cha SEO → Ulinganifu kinatoa hali ya kugundua moja kwa moja na kinaelezea hasa LF inafanya nini kwa kila eneo la kipengele.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL ya kushiriki daima inaonyesha ukurasa wa sasa — hakuna haja ya kuingiza URL kwa mkono. kichungi cha linguaforge_social_share_url hukuruhusu kubadilisha URL iliyotatuliwa kwa huduma yoyote.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Ramani ya tovuti inatangazwa moja kwa moja katika robots.txt. Mengineyo makuu ya injini za utafutaji — Google, Bing, Yandex — yanagundua kutoka robots.txt. Hakuna uwasilishaji wa mkono unaohitajika.','The source page has no footnotes.'=>'Ukurasa wa chanzo haujakuwa na nukuu za mguu wa ukurasa.','The upload failed — please try again.'=>'Upakuaji umeshindwa — tafadhali jaribu tena.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Ramani ya tovuti ya msingi ya WordPress inaorodhesha URL zote za maudhui yako. Ramani ya tovuti ya LF inawaambia injini za utafutaji jinsi toleo za lugha zinavyohusiana kwa njia ya xhtml:link hreflang mbadala. Wasilisha zote kwa Google Search Console kwa ufanisi kamili.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Nukuu hizi za mguu wa ukurasa zinatoka kwenye ukurasa wa chanzo na zinaonyeshwa hapa kwa marejeo tu. Ziongeze kwenye ukurasa huu kwa kutumia mhariri wa vikundi.','This is the source page. Footnotes are edited directly in the block editor.'=>'Hii ni ukurasa wa chanzo. Nukuu za mguu wa ukurasa huhaririwa moja kwa moja kwenye mhariri wa vikundi.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Funguo hili kwa sasa linatolewa na seva %s na haliwezi kuondolewa hapa. Ingiza funguo mpya juu ili kuilinda na thamani ya hifadhidata.','This language is protected and cannot be uninstalled.'=>'Lugha hii inalindwa na haiwezi kufutwa.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Lugha hii inalingana na eneo la WordPress na haiwezi kufutwa.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: ili kurejesha mfano kwa chaguo-msingi cha ndani, safisha uwanja na hifadhi.','Title'=>'Kichwa','Title is %1$d chars — aim for %2$d–%3$d.'=>'Kichwa ni herufi %1$d — lengo ni %2$d–%3$d.','Title is %1$d chars — may be truncated in SERPs (aim for %2$d–%3$d).'=>'Kichwa ni %1$d herufi — inaweza kukatwa katika SERPs (lengo ni %2$d–%3$d).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Ili kutumia siri ya usimbuaji wa desturi (badala ya thamani ya wp_salt iliyotolewa), ongeza hii katika wp-config.php:','Today'=>'Leo','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Matumizi ya token yamekusanywa kwa kipengele, mtoa huduma, na mfano. Yamehifadhiwa kwenye kila simu ya mafanikio ya AI; ping za Jaribio la Muunganisho hazijumuishwa ili zisibakize jumla.','Tone'=>'Mwelekeo','tone'=>'sauti','Tone:'=>'Sauti:','Too many AI requests. Please retry in %d seconds.'=>'Orodha nyingi za AI. Tafadhali jaribu tena kwa sekunde %d.','Total'=>'Jumla','Total tokens'=>'Jumla ya token','Translate'=>'Tafsiri','Translate / Revise'=>'Tafsiri / Badilisha','Translate / Revise block'=>'Kifungu cha Tafsiri / Badilisha','Translate all'=>'Tafsiri zote','Translate chunk'=>'Tafsiri sehemu','Translate Content'=>'Tafsiri Maudhui','Translate missing'=>'Tafsiri isiyokamilika','Translate page…'=>'Tafsiri ukurasa…','Translated content'=>'Yaliyomo yaliyotafsiriwa','Translated Names'=>'Majina yaliyotafsiriwa','Translated title'=>'Kichwa kilichotafsiriwa','Translated to:'=>'Imetafsiriwa kwa:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Imetafsiriwa. Pitia kwenye Mhariri wa Tovuti — viungo vya ndani, URLs za urambazaji, na majina ya kiolezo hayasaswi kiotomatiki.','Translating…'=>'Inatafsiri…','Translation'=>'Tafsiri','Translation Caching'=>'Kuhifadhi Kumbukumbu za Tafsiri','Translation found but permalink could not be generated'=>'Utaratibu umegunduliwa lakini kiungo cha kudumu hakikuweza kutengenezwa','Translation Limits'=>'Mipaka ya Tafsiri','Translation Limits & Behavior'=>'Mipaka ya Tafsiri & Tabia','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Mipaka ya Tafsiri: kudhibiti ni majukumu ya aina gani za watumiaji wanaweza kuanzisha tafsiri ya AI, na kuweka bajeti ya token kwa mwezi. Kupita bajeti kunasababisha kusitisha simu za AI hadi mwezi ujao utakapobadilika.','Translation Memory'=>'Kumbukumbu ya Tafsiri','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Kumbukumbu za Tafsiri hufanya kazi kwa kuhifadhi matokeo ya AI kwa hash ya maudhui, jozi ya lugha, mtoa huduma, na mfano. Kuhariri chapisho kunavunjilia mbali kumbukumbu ili simu inayofuata ya tafsiri ipate matokeo mapya.','Translation Memory cleared. %d cached block was removed.'=>'Kumbukumbu ya Tafsiri imefutwa. Kipande cha cache %d kiliondolewa.' . "\0" . 'Kumbukumbu ya Tafsiri imefutwa. Vipande %d vya cache vimeondolewa.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Kumbukumbu za Tafsiri: hifadhi chapisho kamili kilichotafsiriwa kwa kila hash ya maudhui. Futa wakati unataka kulazimisha tafsiri upya ya maudhui yote bila kujali kama yaliyobadilika.','Translation workflow'=>'Mchakato wa Tafsiri','Translation, Content Generator'=>'Tafsiri, Mwandishi wa Maudhui','Treat H2 as H1 equivalent'=>'Tafsiri H2 kama H1 sawa','Type'=>'Aina','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Futa %s','Uninstall Behaviour'=>'Futa Tabia ya Kifuta','Uninstall setting saved.'=>'Mipangilio ya kufuta imesimamiwa.','unknown error'=>'hitilafu isiyojulikana','Unknown provider.'=>'Mtoa huduma haijulikani.','Unknown search engine.'=>'Injini ya utafutaji isiyojulikana.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Tofauti na hreflang — ambapo LF daima huongeza nguvu plugin nyingine kwa sababu hawawezi kujua usanidi wako wa lugha nyingi — Open Graph ni tofauti: Yoast, Rank Math, na plugins zinazofanana tayari hutoa lebo sahihi za OG kwa maudhui yako. Kuziiga hakutoa thamani yoyote. Katika hali ya kiotomatiki, LF huamua plugin za SEO zinazofanya kazi na huongeza tu kile ambacho hawawezi kutoa: og:locale (lugha ya sasa) na og:locale:alternate (lugha zote zilizowekwa).','Up'=>'Juu','Upload .mo file'=>'Pakua faili ya .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Pakua faili zilizokusanywa za .mo kubadilisha maneno ya programu za watu wengine kwa maeneo maalum — kwa mfano, tafsiri maalum ya VikBooking inayotumia "apartment" badala ya "room". Faili lazima zifuate muundo wa jina la WordPress: {textdomain}-{locale}.mo (mfano, vikbooking-ca.mo). Zina hifadhiwa kwenye folda ya uploads na huishi baada ya sasisho la programu.','Upload Override'=>'Pakua Mabadiliko','URL could not be mapped to a post — check the link target exists'=>'URL haikuweza kuambatana na chapisho — angalia kama lengo la kiungo lipo','URL structure'=>'Muundo wa URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Muundo wa URL: hali ya kiambatanisho cha njia (example.com/de/) hahitaji mabadiliko ya seva. Hali ya subdomain (de.example.com) inahitaji rekodi ya DNS ya wildcard, cheti cha SSL cha wildcard, na mabadiliko ya usanidi wa seva — angalia mwongozo wa Usanidi wa Seva.','URL to enter'=>'URL ya kuingiza','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Tumia kushiriki asili inapopatikana; rudisha nakala kwenye ubao wa kunakili. Pendekezo la chaguo-msingi kwa vitufe vya "Shiriki".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Tumia kanda za juu za ukurasa huu kuunda kila eneo. Mabadiliko kwenye kanda ya Router yanachukua athari mara moja; mabadiliko kwenye funguo za AI na mipangilio ya mfano yanahusiana na ombi lijalo la AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Jedwali la istilahi linaloswa na mtumiaji kwa kila lugha. Viingilio vinaongezwa kwenye maelekezo ya mfumo wa tafsiri ili AI itumie maneno yanayopendelewa kwa utaratibu — muhimu kwa msamiati wa sekta ("kWp", "PPA", "sehemu ya kuunganishwa"), majina ya chapa ambayo hayapaswi kutafsiriwa, na maneno ya kanuni za udhibiti zilizowekwa. Sehemu zote za lugha ni hiari: acha "Lugha ya Chanzo" tupu ili kutumia kiingilio bila kujali unapotafsiri kutoka kwa lugha gani; acha "Lugha ya Malengo" tupu ili kuitekeleza kwa lugha zote za malengo kwa pamoja.','Using custom meta description.'=>'Kutumia maelezo maalum ya meta.','Using LF AI meta description.'=>'Kutumia meta maelezo ya AI ya LF.','Value source'=>'Chanzo cha thamani','View'=>'Tazama','View built-in default'=>'Tazama chaguo-msingi cha kujengwa ndani','View current robots.txt'=>'Tazama robots.txt ya sasa','View details'=>'Tazama maelezo','View Lingua Forge details'=>'Tazama maelezo ya Lingua Forge','Visit plugin site'=>'Tembelea tovuti ya programu-jalizi','Warning:'=>'Onyo:','WebSite'=>'Tovuti','WebSite — front page / blog index'=>'Tovuti — ukurasa wa mbele / orodha ya blogu','What LF provides — and collision avoidance'=>'Kile LF hutoa — na kuepuka migongano','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Kile LF hutoa: lebo za hreflang kwa kila lugha iliyowekwa, lebo za Open Graph na Twitter Card na og:locale na og:locale:alternate, Schema.org JSON-LD na maelezo ya inLanguage, na ramani ya tovuti maalum ya lugha nyingi kwenye /lf-sitemap.xml na viingilio mbadala vya xhtml:link kwa vikundi vyote vya tafsiri.','When another SEO plugin is installed'=>'Wakati plugin nyingine ya SEO imewekwa','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wakati kumbukumbu za kagua zinapokua zimewezeshwa (kupitia kitufe cha chini au kwa kufafanua LINGUAFORGE_AI_DEBUG katika wp-config.php), vipengele vya Tafsiri na template ya FSE huandika maombi yao ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo. Tumia sehemu hii kufuatilia matokeo hayo na kuyaondoa mara umepata unachohitaji — faili zinaweza kukua kwa haraka kwenye kurasa kubwa. Sanidi saraka ya malengo kupitia kichungi cha linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wakati kinachozimwa, wageni wa mara ya kwanza wasio na keki ya lugha na bila kiambishi cha lugha kwenye URL wanapelekwa kwa toleo la lugha linalolingana zaidi. Uelekezaji huachwa ikiwa lugha inayopendelewa na kivinjari si miongoni mwa lugha zinazofanya kazi za router. Mara mgeni anapochagua lugha kupitia kisakinishi, keki inachukua kipaumbele na kichwa cha kivinjari hakitazingatiwa kwa ziara zijazo.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Wakati imewezeshwa, LF hutoa lebo za ziada za meta kwenye kurasa za bidhaa: og:type=product, og:price:amount, og:price:currency, og:availability, na sawa zao za jina la bidhaa zinazotumiwa na Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Wakati imewezeshwa, URL ya ramani ya tovuti inatangazwa moja kwa moja katika robots.txt na hufanyiwa upya wakati maudhui yaliyotafsiriwa yanahifadhiwa.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Wakati Yoast SEO, Rank Math, All in One SEO, au SEOPress iko hai, LF huondoa kiotomatiki lebo zao za hreflang kwa kutumia kichungi. Plugins za SEO kwa ujumla hutoa hreflang kwa msingi wa muundo wa URL wa lugha moja na hawawezi kuzingatia usanidi wako wa mwelekeo wa lugha nyingi; matokeo ya LF daima ni sahihi.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Kiwango cha mfano kinachotumika kwa tafsiri ya kurasa kamili. Ubora unatumia mfano uliowekwa kwenye jedwali la Miundo hapo juu na ni wa kupendekezwa kwa tafsiri sahihi, ya muda mrefu. Badilisha kwa Mwanga ikiwa ni haraka au gharama ndogo ndogo ndizo kipaumbele na maudhui ni mafupi.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Wakati kinapatikana, mu- plugin inashughulikia seti ya OG ya msingi na LF hutoa lebo za lugha pekee (hali ya kiotomatiki). Kuiondoa kunabadilisha LF kuwa hali kamili ya OG moja kwa moja.','WooCommerce'=>'WooCommerce','WooCommerce product price'=>'Bei ya bidhaa ya WooCommerce','WooCommerce SEO settings saved.'=>'Mipangilio ya SEO ya WooCommerce yamehifadhiwa.','WooCommerce store currency'=>'Sarafu ya duka la WooCommerce','Word count'=>'Idadi ya maneno','WP core canonical active (hreflang disabled)'=>'Canonical ya msingi ya WP iko hai (hreflang imezimwa)','WP-CLI reference'=>'Rejea ya WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Andika maombi ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo','XML Sitemap'=>'Ramani ya XML','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Pia unaweza kufafanua funguo kama mabadiliko ya mazingira au mabadiliko ya PHP (mfano katika wp-config.php). Vyanzo hivyo vinatumika kiotomatiki kama mbadala wakati hakuna funguo ya hifadhidata iliyohifadhiwa.','You do not have permission to manage these settings.'=>'Huna ruhusa ya kusimamia mipangilio hii.','You do not have permission to read this post.'=>'Huna ruhusa ya kusoma chapisho hili.','{n} stale path(s)'=>'{n} njia/nyingine zilizobaki','~%d min read'=>'~%d dakika kusoma' . "\0" . '~%d dakika kusoma','— Any source language —'=>'— Yoyote ya lugha ya chanzo —','— Any target language —'=>'— Yoyote ya lugha ya malengo —','— Any target —'=>'— Malengo yote —','— Any —'=>'— Yoyote —','— auto-detect —'=>'— kugundua kiotomatiki —','— Deferred to plugin'=>'— Imesogezwa kwa plugin','— Disabled'=>'— Imelzimwa','— Not detected'=>'— Haijapatikana','— select a language —'=>'— chagua lugha —','— toggle in Settings → Behavior.'=>'— chaguo katika Vipimo → Tabia.','← Back'=>'← Rudi nyuma','↑ Detected from current post'=>'↑ Imegunduliwa kutoka kwa chapisho la sasa','→ Locale tags only (manual setting)'=>'→ Lebo za eneo pekee (uwekaji wa mikono)','→ Locale tags only — deferring base OG to plugin'=>'→ Lebo za eneo pekee — kuahirisha OG msingi kwa programu-jalizi','↺ Re-translate'=>'↺ Tafsiri tena','↺ Refine'=>'↺ Boresha','↺ Refresh'=>'↺ Mvua','↺ Refresh AI Analysis'=>'↺ Sasisha Uchambuzi wa AI','↺ Refreshing…'=>'↺ Inasasishwa…','⚠ Borderline'=>'Hatari ya ukingo ⚠','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Hakuna machapisho <strong>{lang}</strong> yaliyopatikana. Hakikisha machapisho yote yaliyotafsiriwa yana Meta ya Lugha iliyowekwa kuwa <strong>{lang}</strong> kwenye sanduku la Meta la Lugha.','⚠ No changes'=>'⚠ Hakuna mabadiliko','⚠ No changes — re-scan?'=>'⚠ Hakuna mabadiliko — tena uchunguzi?','✅ Fixed ({n})'=>'✅ Imerekebishwa ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Hakuna viungo vilivyovunjika au makosa ya kiolezo yaliyopatikana kwa <strong>{lang}</strong>. Umechunguza machapisho <strong>{scanned}</strong> na kurasa — ukaguzi wote umepita. Viungo vya sehemu za kiolezo (kichwa, mfinyanzi, upendeleo wa upande) havijajumuishwa hapa — tumia kitufe cha Kutatuwa Sehemu za Kiolezo kuangalia tofauti.','✅ Template fixed'=>'✅ Kiolezo kimerekebishwa','✓ %s notified successfully.'=>'✓ %s imeripotiwa kwa mafanikio.','✓ Active'=>'✓ Imo','✓ Active at /lf-sitemap.xml'=>'✓ Imo kwenye /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Imo — ingizo la URL %d lenye mabadiliko ya lugha' . "\0" . '✓ Imo — ingizo la URL %d lenye mabadiliko ya lugha','✓ Active — full OG + Twitter Cards'=>'✓ Imo — OG kamili + Kadi za Twitter','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Imo — lebo za eneo pekee (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Sehemu zote zimetengenezwa.','✓ All templates created.'=>'✓ Kila kiolezo kimeundwa.','✓ All translated.'=>'✓ Zote zimefasirishwa.','✓ Configured'=>'Imesasishwa','✓ Connection OK'=>'✓ Muunganisho mzuri','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Yaliyomo yamezalishwa — angalia juu ili kuangalia, kuboresha, na kutumia.','✓ Done'=>'✓ Imekamilika','✓ Enabled'=>'✓ Imewashwa','✓ Good length'=>'Urefu mzuri ✓','✓ Hreflang active'=>'✓ Hreflang imetumika','✓ In safe storage'=>'✓ Katika hifadhi salama','✓ Language installed.'=>'✓ Lugha imewekwa.','✓ LF outputs'=>'✓ Matokeo ya LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Matokeo ya LF Article / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ Matokeo ya LF OG kamili + Kadi za Twitter','✓ LF outputs — plugin hreflang suppressed'=>'✓ Matokeo ya LF — programu-jalizi hreflang imezuiwa','✓ Links fixed.'=>'✓ Viungo vimerekebishwa.','✓ Nav refs fixed.'=>'✓ Marejeo ya urambazaji yamerekebishwa.','✓ Parts fixed.'=>'✓ Sehemu zimerekebishwa.','✓ Pattern translated.'=>'✓ Mfano umefasirishwa.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Robots.txt ya kimwili imepatikana. Amri ya Ramani ya LF iko.','✓ Refined — review the updated draft above.'=>'✓ Umeboreshwa — hakiki rasimu iliyosasishwa hapo juu.','✓ Translation saved'=>'✓ Tafsiri imehifadhiwa','✓ WP core canonical removed'=>'✓ Msingi wa WP wa canonical umeondolewa','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ %s ping imekosea. URL ya ramani ya tovuti bado inatangazwa kwenye robots.txt — injini ya utafutaji itaiweza kwenye utafutaji wake ujao.','✗ Disabled'=>'✗ Imesimamishwa','✗ Error:'=>'✗ Hitilafu:','✗ Failed:'=>'✗ Imeshindwa:','✗ Not configured'=>'Hijasasishwa','✗ Too long'=>'Mrefu sana ✗','✗ Too short'=>'Mfupi sana ✗','❌ Failed'=>'❌ Imeshindwa','📄 Wrong template'=>'📄 Kiolezo kisicho sahihi','📍 Stale path (page moved)'=>'📍 Njia/nyingine zilizobaki (ukurasa uhamishiwa)']];
